// Structure to hold function pointers for CUDA libraries
typedef struct {
  // cuDSS function pointers
  decltype(&::cudssCreate) cudssCreate;
  decltype(&::cudssConfigCreate) cudssConfigCreate;
  decltype(&::cudssDataCreate) cudssDataCreate;
  decltype(&::cudssMatrixCreateCsr) cudssMatrixCreateCsr;
  decltype(&::cudssExecute) cudssExecute;
  decltype(&::cudssMatrixCreateDn) cudssMatrixCreateDn;
  decltype(&::cudssMatrixSetValues) cudssMatrixSetValues;
  decltype(&::cudssMatrixDestroy) cudssMatrixDestroy;
  decltype(&::cudssDataDestroy) cudssDataDestroy;
  decltype(&::cudssConfigDestroy) cudssConfigDestroy;
  decltype(&::cudssDestroy) cudssDestroy;
  decltype(&::cudssConfigSet) cudssConfigSet;

  // cuSPARSE function pointers
  cusparseStatus_t (*cusparseCreate)(cusparseHandle_t* handle);
  cusparseStatus_t (*cusparseCreateMatDescr)(cusparseMatDescr_t* descr);
  cusparseStatus_t (*cusparseSetMatType)(cusparseMatDescr_t descr,
                                         cusparseMatrixType_t type);
  cusparseStatus_t (*cusparseSetMatIndexBase)(cusparseMatDescr_t descr,
                                              cusparseIndexBase_t base);
  cusparseStatus_t (*cusparseDestroy)(cusparseHandle_t handle);
  cusparseStatus_t (*cusparseDestroyMatDescr)(cusparseMatDescr_t descr);

  decltype(&::cublasSetStream) cublasSetStream;
  decltype(&::cublasSetWorkspace) cublasSetWorkspace;
  decltype(&::cublasGetStream) cublasGetStream;
  decltype(&::cublasSetPointerMode) cublasSetPointerMode;
  decltype(&::cublasGetPointerMode) cublasGetPointerMode;
  // cuBLAS function pointers
  cublasStatus_t (*cublasCreate)(cublasHandle_t* handle);
